<?php
declare(strict_types=1);require_once __DIR__.'/request-supply.php';
function request_campaign_event(string $requestId,string $event,?array $link=null,?string $invitationId=null,array $data=[]):void{db()->prepare('INSERT INTO campaign_events(request_id,campaign_id,share_link_id,invitation_id,event_type,attribution) VALUES(?,?,?,?,?,?)')->execute([$requestId,$link['campaign_id']??null,$link['id']??null,$invitationId,$event,$data?json_encode($data,JSON_THROW_ON_ERROR):null]);}
function request_share_create(array $user,string $requestId,string $accessType='PUBLIC',?string $campaignId=null,?string $expiresAt=null):array{$request=request_owned($user,$requestId,true);if(!in_array($request['status'],['OPEN','RESPONSES_RECEIVED'],true)||$request['response_deadline']<=gmdate('Y-m-d H:i:s'))throw new DomainException('Publish or reopen this request before distributing it.',409);$accessType=marketplace_enum(['access_type'=>$accessType],'access_type',['PUBLIC','PRIVATE_LINK','INVITATION']);if($accessType==='PUBLIC'&&$request['visibility']!=='PUBLIC')throw new DomainException('A private request cannot use a public share link. Choose private link instead.',409);$existing=$accessType==='INVITATION'?null:(rows('SELECT * FROM request_share_links WHERE request_id=? AND access_type=? AND campaign_id <=> ? AND revoked_at IS NULL AND (expires_at IS NULL OR expires_at>UTC_TIMESTAMP()) ORDER BY created_at DESC LIMIT 1',[$requestId,$accessType,$campaignId])[0]??null);if($existing)return $existing;$id=uuid();$token=bin2hex(random_bytes(24));db()->prepare('INSERT INTO request_share_links(id,request_id,token,access_type,campaign_id,expires_at,created_by) VALUES(?,?,?,?,?,?,?)')->execute([$id,$requestId,$token,$accessType,$campaignId,$expiresAt,$user['id']]);$link=rows('SELECT * FROM request_share_links WHERE id=?',[$id])[0];request_campaign_event($requestId,'LINK_CREATED',$link,null,['access_type'=>$accessType]);request_event($requestId,$user,'SHARE_LINK_CREATED',['share_link_id'=>$id,'access_type'=>$accessType]);return $link;}
function request_share_resolve(string $token,bool $recordView=true):array{$link=rows("SELECT sl.*,r.status request_status,r.visibility request_visibility,r.response_deadline FROM request_share_links sl JOIN marketplace_requests r ON r.id=sl.request_id WHERE sl.token=? AND sl.revoked_at IS NULL AND (sl.expires_at IS NULL OR sl.expires_at>UTC_TIMESTAMP())",[$token])[0]??null;if(!$link)throw new DomainException('This request link is invalid or has expired.',404);if(!in_array($link['request_status'],['OPEN','RESPONSES_RECEIVED'],true)||$link['response_deadline']<=gmdate('Y-m-d H:i:s'))throw new DomainException('This request is no longer accepting responses.',410);if($recordView){$invitation=rows("SELECT id FROM supplier_invitations WHERE share_link_id=? AND status='SENT' ORDER BY sent_at DESC LIMIT 1",[$link['id']])[0]['id']??null;if($invitation)db()->prepare("UPDATE supplier_invitations SET status='VIEWED',viewed_at=UTC_TIMESTAMP() WHERE id=?")->execute([$invitation]);request_campaign_event($link['request_id'],'REQUEST_VIEWED',$link,$invitation,['source'=>(string)($_GET['src']??'share')]);}return $link;}
function request_campaign_create(array $user,string $requestId,array $input):array{request_owned($user,$requestId,true);$channel=marketplace_enum($input,'channel',['SUPPLIER_NETWORK','SELECTED_SUPPLIERS','EMAIL','WHATSAPP','DIRECT_LINK','SOCIAL','PAID']);$id=uuid();db()->prepare("INSERT INTO distribution_campaigns(id,request_id,channel,created_by,audience_definition,approved_content,status,started_at) VALUES(?,?,?,?,?,?,'ACTIVE',UTC_TIMESTAMP())")->execute([$id,$requestId,$channel,$user['id'],json_encode(['audience'=>marketplace_text($input,'audience',1000)],JSON_THROW_ON_ERROR),marketplace_text($input,'approved_content',5000)]);request_event($requestId,$user,'DISTRIBUTION_STARTED',['campaign_id'=>$id,'channel'=>$channel]);return rows('SELECT * FROM distribution_campaigns WHERE id=?',[$id])[0];}
function request_invite_supplier(array $user,string $requestId,array $input):array{$request=request_owned($user,$requestId,true);$channel=marketplace_enum($input,'channel',['EMAIL','WHATSAPP','DIRECT_LINK','SUPPLIER_NETWORK'],'EMAIL');$link=request_share_create($user,$requestId,'INVITATION',null,$request['response_deadline']);$id=uuid();db()->prepare('INSERT INTO supplier_invitations(id,request_id,share_link_id,contact_name,contact_email,contact_phone,channel,invited_by) VALUES(?,?,?,?,?,?,?,?)')->execute([$id,$requestId,$link['id'],marketplace_text($input,'contact_name',255),marketplace_text($input,'contact_email',255),marketplace_text($input,'contact_phone',50),$channel,$user['id']]);request_campaign_event($requestId,'INVITATION_SENT',$link,$id,['channel'=>$channel]);return ['id'=>$id,'token'=>$link['token']];}
function request_external_response(array $link,array $input,array $file):string{$request=rows('SELECT * FROM marketplace_requests WHERE id=?',[$link['request_id']])[0];$amount=marketplace_number($input,'amount');if($amount<=0)throw new DomainException('Enter a positive rate or purchase price.',422);$currency=strtoupper(marketplace_text($input,'currency',3,true));if(!preg_match('/^[A-Z]{3}$/',$currency))throw new DomainException('Use a three-letter currency code.',422);$document=[null,null,null];if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||($file['size']??0)>10*1024*1024)throw new DomainException('Upload one supporting document up to 10 MB.',422);$mime=(new finfo(FILEINFO_MIME_TYPE))->file((string)$file['tmp_name']);$allowed=['application/pdf','image/jpeg','image/png','application/vnd.openxmlformats-officedocument.wordprocessingml.document'];if(!in_array($mime,$allowed,true))throw new DomainException('Upload a PDF, DOCX, JPEG or PNG document.',422);$document=[substr(basename((string)$file['name']),0,255),$mime,file_get_contents((string)$file['tmp_name'])];}$invitation=rows("SELECT id FROM supplier_invitations WHERE share_link_id=? AND status IN ('SENT','VIEWED') ORDER BY sent_at DESC LIMIT 1",[$link['id']])[0]['id']??null;$id=uuid();db()->prepare('INSERT INTO external_supplier_responses(id,request_id,share_link_id,invitation_id,contact_name,company_name,contact_email,contact_phone,equipment_description,oem_name,model_name,availability_from,availability_until,quantity_offered,amount,currency,pricing_basis,technical_response,notes,document_name,document_mime,document_data) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$request['id'],$link['id'],$invitation,marketplace_text($input,'contact_name',255,true),marketplace_text($input,'company_name',255,true),marketplace_text($input,'contact_email',255,true),marketplace_text($input,'contact_phone',50),marketplace_text($input,'equipment_description',5000,true),marketplace_text($input,'oem_name',255),marketplace_text($input,'model_name',255),marketplace_text($input,'availability_from',10,true),marketplace_text($input,'availability_until',10),max(1,(int)($input['quantity_offered']??1)),$amount,$currency,marketplace_enum($input,'pricing_basis',['HOURLY','DAILY','WEEKLY','MONTHLY','PROJECT','FIXED']),marketplace_text($input,'technical_response',5000),marketplace_text($input,'notes',5000),...$document]);if($invitation)db()->prepare("UPDATE supplier_invitations SET status='RESPONDED',responded_at=UTC_TIMESTAMP() WHERE id=?")->execute([$invitation]);request_campaign_event($request['id'],'OFFER_SUBMITTED',$link,$invitation,['external_response_id'=>$id]);request_event($request['id'],null,'EXTERNAL_RESPONSE_SUBMITTED',['external_response_id'=>$id]);return $id;}
